    ['message_key' => 'validation_error', 'message_value' => 'Please fix the validation errors before submitting.', 'category' => 'error'],
    ['message_key' => 'wishlist_added', 'message_value' => 'Added to wishlist!', 'category' => 'success'],
    ['message_key' => 'zone_duplicate_error', 'message_value' => 'An active zone for this location already exists.', 'category' => 'error'],
    ['message_key' => 'zone_location_required', 'message_value' => 'Please select a location via the map first.', 'category' => 'error'],
    ['message_key' => 'zone_polygon_missing', 'message_value' => 'No polygon data for this zone.', 'category' => 'error'],
    ['message_key' => 'zone_polygon_render_failed', 'message_value' => 'Could not render polygon on map.', 'category' => 'error'],
    ['message_key' => 'User not found', 'message_value' => 'message', 'category' => 'info'],
    ['message_key' => 'product_images_required', 'message_value' => 'At least one product image is required', 'category' => 'info'],
    ['message_key' => 'Free', 'message_value' => 'subscription_tier', 'category' => 'info']
];

$inserted = 0;
$skipped  = 0;
$now      = date('Y-m-d H:i:s');

$checkStmt  = $pdo->prepare("SELECT COUNT(*) FROM `app_messages` WHERE `message_key` = :key");
$insertStmt = $pdo->prepare("INSERT INTO `app_messages` (`message_key`, `message_value`, `category`, `created_at`, `updated_at`) VALUES (:key, :val, :cat, :now, :now)");

foreach ($messages as $msg) {
    $checkStmt->execute([':key' => $msg['message_key']]);
    $count = (int) $checkStmt->fetchColumn();

    if ($count === 0) {
        $insertStmt->execute([
            ':key' => $msg['message_key'],
            ':val' => $msg['message_value'],
            ':cat' => $msg['category'],
            ':now' => $now,
        ]);
        echo "  INSERTED: {$msg['message_key']}\n";
        $inserted++;
    } else {
        echo "  SKIPPED:  {$msg['message_key']}\n";
        $skipped++;
    }
}

echo "\nDone. Inserted: $inserted | Skipped: $skipped\n";
